//! Schema-generated attribute tables for the ESPF `# components` elements.
//!
//! [`generated_elements`] holds one typed `Attrs` struct per element, compiled
//! from `espf.schema.kdl` by `build.rs`; [`attrs`] is the coercion layer that
//! turns a spelling into a typed value with its span. Lowering reads these
//! directly, so an element's attribute contract is written once, in the schema.
//!
//! [`TAGS`] is the same schema's list of bus-component tags, kept so the
//! catalog and the schema cannot drift.

pub mod attrs;
pub mod generated_elements;

// Generated by build.rs from the one element schema (`espf.schema.kdl`), so
// the list of tags is not written down twice.
mod generated_vocab;

/// The bus-component tags the schema marks `bus_component=#true`.
pub use generated_vocab::TAGS;
